This Redux thunk applies gift cards at checkout. Restructure it so the redemption logic is independent of Redux and fetch:

```typescript
export const applyGiftCards = (codes: string[]) => async (dispatch: AppDispatch, getState: () => RootState) => {
  let due = getState().checkout.totalCents;
  const applied: { code: string; usedCents: number }[] = [];
  for (const code of codes.slice(0, 3)) {
    const res = await fetch(`/api/gift-cards/${encodeURIComponent(code)}`);
    if (!res.ok) { dispatch(checkoutError(`Gift card ${code} not found`)); return; }
    const card = await res.json();
    if (card.currency !== getState().checkout.currency) { dispatch(checkoutError('Currency mismatch')); return; }
    if (new Date(card.expiresOn) < new Date()) continue;
    const used = Math.min(card.balanceCents, due);
    if (used > 0) applied.push({ code, usedCents: used });
    due -= used;
    if (due === 0) break;
  }
  dispatch(giftCardsApplied({ applied, remainingCents: due }));
};
```

### Architectural Flaws in Original Code
1. **Redemption rules inside a thunk:** the three-card limit, currency check, expiry skip and balance allocation are tied to Redux.
2. **HTTP in the state layer:** `fetch` and the URL format are mixed with business decisions.
3. **Untyped card payload:** `res.json()` is trusted without a shape check.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/giftCards.ts`)
```typescript
import { Result } from '../shared/Result';

export interface GiftCard {
  readonly code: string;
  readonly balanceCents: number;
  readonly currency: string;
  readonly expiresOn: Date;
}

export interface Allocation {
  readonly applied: readonly { code: string; usedCents: number }[];
  readonly remainingCents: number;
}

export type GiftCardError = { kind: 'NotFound'; code: string } | { kind: 'CurrencyMismatch'; code: string };

export const MAX_CARDS = 3;

/** Spends cards in order until the amount is covered; expired cards are skipped. */
export function allocate(
  cards: readonly GiftCard[], dueCents: number, currency: string, today: Date,
): Result<Allocation, GiftCardError> {
  let remaining = dueCents;
  const applied: { code: string; usedCents: number }[] = [];
  for (const card of cards) {
    if (card.currency !== currency) return Result.fail({ kind: 'CurrencyMismatch', code: card.code });
    if (card.expiresOn < today) continue;
    const used = Math.min(card.balanceCents, remaining);
    if (used > 0) applied.push({ code: card.code, usedCents: used });
    remaining -= used;
    if (remaining === 0) break;
  }
  return Result.ok({ applied, remainingCents: remaining });
}
```

#### 2. Application Layer (`src/application/ApplyGiftCards.ts`)
Cards are looked up in order, so a missing card is reported only if it would have been reached before the total was covered.
```typescript
import { Result } from '../shared/Result';
import { Allocation, GiftCard, GiftCardError, MAX_CARDS, allocate } from '../domain/giftCards';

export interface GiftCardLookup {
  find(code: string): Promise<GiftCard | null>;
}

export class ApplyGiftCards {
  constructor(private readonly lookup: GiftCardLookup, private readonly today: () => Date) {}

  async execute(codes: readonly string[], dueCents: number, currency: string): Promise<Result<Allocation, GiftCardError>> {
    const cards: GiftCard[] = [];
    for (const code of codes.slice(0, MAX_CARDS)) {
      const card = await this.lookup.find(code);
      if (!card) return Result.fail({ kind: 'NotFound', code });
      cards.push(card);
      const partial = allocate(cards, dueCents, currency, this.today());
      if (!partial.success || partial.data.remainingCents === 0) return partial;
    }
    return allocate(cards, dueCents, currency, this.today());
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/HttpGiftCardLookup.ts`)
```typescript
import { GiftCard } from '../domain/giftCards';
import { GiftCardLookup } from '../application/ApplyGiftCards';

interface GiftCardDto { balanceCents: number; currency: string; expiresOn: string; }

function isGiftCardDto(v: unknown): v is GiftCardDto {
  if (typeof v !== 'object' || v === null) return false;
  const d = v as Record<string, unknown>;
  return typeof d.balanceCents === 'number' && typeof d.currency === 'string' && typeof d.expiresOn === 'string';
}

export class HttpGiftCardLookup implements GiftCardLookup {
  async find(code: string): Promise<GiftCard | null> {
    const res = await fetch(`/api/gift-cards/${encodeURIComponent(code)}`);
    if (!res.ok) return null;
    const body: unknown = await res.json();
    if (!isGiftCardDto(body)) return null;
    return { code, balanceCents: body.balanceCents, currency: body.currency, expiresOn: new Date(body.expiresOn) };
  }
}
```

#### 4. Presentation Layer (thin thunk)
```typescript
export const applyGiftCards = (codes: string[]) => async (dispatch: AppDispatch, getState: () => RootState) => {
  const { totalCents, currency } = getState().checkout;
  const result = await applyGiftCardsUseCase.execute(codes, totalCents, currency);
  if (result.success) {
    dispatch(giftCardsApplied({ applied: [...result.data.applied], remainingCents: result.data.remainingCents }));
  } else if (result.error.kind === 'NotFound') {
    dispatch(checkoutError(`Gift card ${result.error.code} not found`));
  } else {
    dispatch(checkoutError('Currency mismatch'));
  }
};
```

Refactor this Next.js route handler for cancelling a gym class booking. When a spot frees up, the first person on the waitlist is promoted. Keep Prisma and Next out of the rules:

```typescript
export async function DELETE(req: NextRequest, { params }: { params: { bookingId: string } }) {
  const booking = await prisma.booking.findUnique({ where: { id: params.bookingId }, include: { session: true } });
  if (!booking) return NextResponse.json({ error: 'Not found' }, { status: 404 });
  const hoursBefore = (booking.session.startsAt.getTime() - Date.now()) / 3600000;
  if (hoursBefore < 0) return NextResponse.json({ error: 'Class already started' }, { status: 409 });
  const lateFee = hoursBefore < 12 ? 5 : 0;
  await prisma.$transaction(async (tx) => {
    await tx.booking.delete({ where: { id: booking.id } });
    if (lateFee > 0) await tx.charge.create({ data: { memberId: booking.memberId, amount: lateFee, reason: 'late_cancel' } });
    const next = await tx.waitlistEntry.findFirst({ where: { sessionId: booking.sessionId }, orderBy: { createdAt: 'asc' } });
    if (next) {
      await tx.waitlistEntry.delete({ where: { id: next.id } });
      await tx.booking.create({ data: { sessionId: booking.sessionId, memberId: next.memberId } });
    }
  });
  return NextResponse.json({ lateFee });
}
```

### Architectural Flaws in Original Code
1. **Cancellation policy in a route handler:** the 12-hour window, the late fee and waitlist promotion are only reachable through Next.js.
2. **Transaction logic tied to Prisma:** the rules are written as `tx.*` calls instead of domain operations.
3. **Time read inline:** `Date.now()` makes the late-fee boundary hard to test.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/cancellation.ts`)
```typescript
import { Result } from '../shared/Result';

export type CancelError = { kind: 'BookingNotFound' } | { kind: 'ClassStarted' };

export interface Booking {
  readonly id: string;
  readonly memberId: string;
  readonly sessionId: string;
  readonly sessionStartsAt: Date;
}

export interface CancellationOutcome {
  readonly lateFee: number;
}

export const LATE_WINDOW_HOURS = 12;
export const LATE_FEE = 5;

export function cancellationOutcome(booking: Booking, now: Date): Result<CancellationOutcome, CancelError> {
  const hoursBefore = (booking.sessionStartsAt.getTime() - now.getTime()) / 3_600_000;
  if (hoursBefore < 0) return Result.fail({ kind: 'ClassStarted' });
  return Result.ok({ lateFee: hoursBefore < LATE_WINDOW_HOURS ? LATE_FEE : 0 });
}
```

#### 2. Application Layer (`src/application/CancelBooking.ts`)
```typescript
import { Result } from '../shared/Result';
import { Booking, CancelError, CancellationOutcome, cancellationOutcome } from '../domain/cancellation';

/** Operations that must run atomically while cancelling. */
export interface CancellationUnit {
  removeBooking(bookingId: string): Promise<void>;
  chargeLateFee(memberId: string, amount: number): Promise<void>;
  /** Removes and returns the oldest waitlisted member, if any. */
  popWaitlist(sessionId: string): Promise<string | null>;
  book(sessionId: string, memberId: string): Promise<void>;
}

export interface BookingStore {
  find(bookingId: string): Promise<Booking | null>;
  inTransaction<T>(work: (unit: CancellationUnit) => Promise<T>): Promise<T>;
}

export class CancelBooking {
  constructor(private readonly bookings: BookingStore, private readonly now: () => Date) {}

  async execute(bookingId: string): Promise<Result<CancellationOutcome, CancelError>> {
    const booking = await this.bookings.find(bookingId);
    if (!booking) return Result.fail({ kind: 'BookingNotFound' });

    const outcome = cancellationOutcome(booking, this.now());
    if (!outcome.success) return outcome;

    await this.bookings.inTransaction(async (unit) => {
      await unit.removeBooking(booking.id);
      if (outcome.data.lateFee > 0) await unit.chargeLateFee(booking.memberId, outcome.data.lateFee);
      const promoted = await unit.popWaitlist(booking.sessionId);
      if (promoted) await unit.book(booking.sessionId, promoted);
    });
    return outcome;
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/PrismaBookingStore.ts`)
```typescript
import { PrismaClient, Prisma } from '@prisma/client';
import { Booking } from '../domain/cancellation';
import { BookingStore, CancellationUnit } from '../application/CancelBooking';

export class PrismaBookingStore implements BookingStore {
  constructor(private readonly prisma: PrismaClient) {}

  async find(bookingId: string): Promise<Booking | null> {
    const b = await this.prisma.booking.findUnique({ where: { id: bookingId }, include: { session: true } });
    return b ? { id: b.id, memberId: b.memberId, sessionId: b.sessionId, sessionStartsAt: b.session.startsAt } : null;
  }

  inTransaction<T>(work: (unit: CancellationUnit) => Promise<T>): Promise<T> {
    return this.prisma.$transaction((tx: Prisma.TransactionClient) => work({
      removeBooking: async (id) => { await tx.booking.delete({ where: { id } }); },
      chargeLateFee: async (memberId, amount) => {
        await tx.charge.create({ data: { memberId, amount, reason: 'late_cancel' } });
      },
      popWaitlist: async (sessionId) => {
        const next = await tx.waitlistEntry.findFirst({ where: { sessionId }, orderBy: { createdAt: 'asc' } });
        if (!next) return null;
        await tx.waitlistEntry.delete({ where: { id: next.id } });
        return next.memberId;
      },
      book: async (sessionId, memberId) => { await tx.booking.create({ data: { sessionId, memberId } }); },
    }));
  }
}
```

#### 4. Presentation Layer (`app/api/bookings/[bookingId]/route.ts`)
```typescript
