```typescript
import express from 'express';
import { Pool } from 'pg';

const pool = new Pool();
export const router = express.Router();

router.post('/prescriptions/:id/refill', async (req, res) => {
  const { rows } = await pool.query('SELECT * FROM prescriptions WHERE id = $1', [req.params.id]);
  const rx = rows[0];
  if (!rx) return res.status(404).send('Not found');
  if (rx.refills_left <= 0) return res.status(409).send('No refills left');
  if (new Date(rx.expires_at) < new Date()) return res.status(410).send('Prescription expired');
  const daysSinceLast = (Date.now() - new Date(rx.last_filled_at).getTime()) / 86400000;
  if (daysSinceLast < rx.days_supply * 0.75) return res.status(429).send('Too early to refill');
  await pool.query(
    'UPDATE prescriptions SET refills_left = refills_left - 1, last_filled_at = now() WHERE id = $1',
    [rx.id],
  );
  res.json({ refillsLeft: rx.refills_left - 1 });
});

```

### Architectural Flaws in Original Code
1. **Clinical rules in a router:** refill count, expiry and the 75%-of-supply waiting period are only reachable through Express.
2. **SQL rows as the model:** `rx.refills_left` and friends are untyped database columns.
3. **Two clocks:** `new Date()` in the handler and `now()` in SQL can disagree.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Prescription.ts`)
```typescript
import { Result } from '../shared/Result';

export type RefillError =
  | { kind: 'NotFound' }
  | { kind: 'NoRefillsLeft' }
  | { kind: 'Expired' }
  | { kind: 'TooEarly'; earliest: Date };

export class Prescription {
  static readonly EARLY_REFILL_RATIO = 0.75;

  constructor(
    readonly id: string,
    private refillsLeft: number,
    readonly expiresAt: Date,
    private lastFilledAt: Date,
    readonly daysSupply: number,
  ) {}

  get remainingRefills(): number { return this.refillsLeft; }
  get lastFilled(): Date { return this.lastFilledAt; }

  refill(now: Date): Result<void, RefillError> {
    if (this.refillsLeft <= 0) return Result.fail({ kind: 'NoRefillsLeft' });
    if (this.expiresAt < now) return Result.fail({ kind: 'Expired' });
    const waitMs = this.daysSupply * Prescription.EARLY_REFILL_RATIO * 86_400_000;
    const earliest = new Date(this.lastFilledAt.getTime() + waitMs);
    if (now < earliest) return Result.fail({ kind: 'TooEarly', earliest });
    this.refillsLeft -= 1;
    this.lastFilledAt = now;
    return Result.ok(undefined);
  }
}
```

#### 2. Application Layer (`src/application/RefillPrescription.ts`)
```typescript
import { Result } from '../shared/Result';
import { Prescription, RefillError } from '../domain/Prescription';

export interface PrescriptionRepository {
  findById(id: string): Promise<Prescription | null>;
  save(prescription: Prescription): Promise<void>;
}

export class RefillPrescription {
  constructor(private readonly prescriptions: PrescriptionRepository, private readonly now: () => Date) {}

  async execute(id: string): Promise<Result<number, RefillError>> {
    const rx = await this.prescriptions.findById(id);
    if (!rx) return Result.fail({ kind: 'NotFound' });
    const refilled = rx.refill(this.now());
    if (!refilled.success) return refilled;
    await this.prescriptions.save(rx);
    return Result.ok(rx.remainingRefills);
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/PgPrescriptionRepository.ts`)
```typescript
import { Pool } from 'pg';
import { Prescription } from '../domain/Prescription';
import { PrescriptionRepository } from '../application/RefillPrescription';

interface PrescriptionRow {
  id: string; refills_left: number; expires_at: Date; last_filled_at: Date; days_supply: number;
}

export class PgPrescriptionRepository implements PrescriptionRepository {
  constructor(private readonly pool: Pool) {}

  async findById(id: string): Promise<Prescription | null> {
    const { rows } = await this.pool.query<PrescriptionRow>('SELECT * FROM prescriptions WHERE id = $1', [id]);
    const r = rows[0];
    return r ? new Prescription(r.id, r.refills_left, r.expires_at, r.last_filled_at, r.days_supply) : null;
  }

  async save(rx: Prescription): Promise<void> {
    await this.pool.query('UPDATE prescriptions SET refills_left = $2, last_filled_at = $3 WHERE id = $1',
      [rx.id, rx.remainingRefills, rx.lastFilled]);
  }
}
```

#### 4. Presentation Layer (`src/http/prescriptionRouter.ts`)
```typescript
import express from 'express';
import { RefillError } from '../domain/Prescription';
import { RefillPrescription } from '../application/RefillPrescription';

function toHttp(error: RefillError): [number, string] {
  switch (error.kind) {
    case 'NotFound': return [404, 'Not found'];
    case 'NoRefillsLeft': return [409, 'No refills left'];
    case 'Expired': return [410, 'Prescription expired'];
    case 'TooEarly': return [429, 'Too early to refill'];
  }
}

export function prescriptionRouter(refill: RefillPrescription): express.Router {
  const router = express.Router();
  router.post('/prescriptions/:id/refill', async (req, res) => {
    const result = await refill.execute(req.params.id);
    if (result.success) return res.json({ refillsLeft: result.data });
    const [status, message] = toHttp(result.error);
    res.status(status).send(message);
  });
  return router;
}
```
The router is now built from an injected use case; the `Pool` is created only in the composition root.

Refactor the following javascript code to adhere strictly to Clean Architecture and Ports & Adapters:

```javascript
const db = require('../db');
const mailer = require('../mailer');

async function requestLeave(employeeId, start, end, type) {
  const employee = await db.employees.findById(employeeId);
  const from = new Date(start);
  const to = new Date(end);
  if (to < from) throw new Error('End before start');
  let days = 0;
  for (let d = new Date(from); d <= to; d.setDate(d.getDate() + 1)) {
    if (d.getDay() !== 0 && d.getDay() !== 6) days++;
  }
  if (type === 'vacation' && days > employee.vacationBalance) throw new Error('Not enough balance');
  if (type === 'sick' && days > 3 && !employee.hasMedicalNote) throw new Error('Medical note required');
  const leave = await db.leaves.insert({ employeeId, start: from, end: to, type, days, status: 'pending' });
  await mailer.send(employee.managerEmail, 'Leave request', `${employee.name} requested ${days} day(s)`);
  return leave;
}

module.exports = { requestLeave };

```

### Architectural Flaws in Original Code
1. **HR policy mixed with I/O:** working-day counting, vacation balance and the sick-leave note rule share a function with database and mail calls.
2. **Module-level singletons:** `require('../db')` and `require('../mailer')` cannot be replaced in tests.
3. **Thrown strings:** callers must parse error messages to know why a request failed.
4. **Missing employee is not handled:** `employee` may be `undefined`.

---

### Clean Architecture Refactoring (TypeScript)

#### 1. Domain Layer (`src/domain/leave.ts`)
```typescript
import { Result } from '../shared/Result';

export type LeaveType = 'vacation' | 'sick' | 'unpaid';

export type LeaveError =
  | { kind: 'EmployeeNotFound' }
  | { kind: 'InvalidRange' }
  | { kind: 'InsufficientBalance'; requested: number; available: number }
  | { kind: 'MedicalNoteRequired' };

export interface Employee {
  readonly id: string;
  readonly name: string;
  readonly managerContact: string;
  readonly vacationBalance: number;
  readonly hasMedicalNote: boolean;
}

export interface LeaveRequest {
  readonly employeeId: string;
  readonly start: Date;
  readonly end: Date;
  readonly type: LeaveType;
  readonly days: number;
  readonly status: 'pending';
}

export const SICK_DAYS_WITHOUT_NOTE = 3;

export function workingDays(from: Date, to: Date): number {
  let days = 0;
  for (const d = new Date(from); d <= to; d.setDate(d.getDate() + 1)) {
    if (d.getDay() !== 0 && d.getDay() !== 6) days++;
  }
  return days;
}

export function requestLeave(
  employee: Employee, start: Date, end: Date, type: LeaveType,
): Result<LeaveRequest, LeaveError> {
  if (end < start) return Result.fail({ kind: 'InvalidRange' });
  const days = workingDays(start, end);
  if (type === 'vacation' && days > employee.vacationBalance) {
    return Result.fail({ kind: 'InsufficientBalance', requested: days, available: employee.vacationBalance });
  }
  if (type === 'sick' && days > SICK_DAYS_WITHOUT_NOTE && !employee.hasMedicalNote) {
    return Result.fail({ kind: 'MedicalNoteRequired' });
  }
  return Result.ok({ employeeId: employee.id, start, end, type, days, status: 'pending' });
}
```

#### 2. Application Layer (`src/application/SubmitLeaveRequest.ts`)
```typescript
import { Result } from '../shared/Result';
import { Employee, LeaveError, LeaveRequest, LeaveType, requestLeave } from '../domain/leave';

export interface EmployeeDirectory { findById(id: string): Promise<Employee | null>; }
export interface LeaveRepository { add(request: LeaveRequest): Promise<LeaveRequest>; }
export interface ManagerNotifier { leaveRequested(manager: string, employeeName: string, days: number): Promise<void>; }

export class SubmitLeaveRequest {
  constructor(
    private readonly employees: EmployeeDirectory,
    private readonly leaves: LeaveRepository,
    private readonly notifier: ManagerNotifier,
  ) {}

  async execute(input: { employeeId: string; start: Date; end: Date; type: LeaveType }): Promise<Result<LeaveRequest, LeaveError>> {
    const employee = await this.employees.findById(input.employeeId);
    if (!employee) return Result.fail({ kind: 'EmployeeNotFound' });

    const request = requestLeave(employee, input.start, input.end, input.type);
    if (!request.success) return request;

    const saved = await this.leaves.add(request.data);
    await this.notifier.leaveRequested(employee.managerContact, employee.name, saved.days);
    return Result.ok(saved);
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/leaveAdapters.ts`)
The existing `db` and `mailer` modules are wrapped instead of imported by the business code.
```typescript
import { LeaveRequest } from '../domain/leave';
import { LeaveRepository, ManagerNotifier } from '../application/SubmitLeaveRequest';

interface LeavesTable { insert(row: LeaveRequest): Promise<LeaveRequest>; }
interface Mailer { send(to: string, subject: string, body: string): Promise<void>; }

export class DbLeaveRepository implements LeaveRepository {
  constructor(private readonly leaves: LeavesTable) {}
