}
```
A `DbEmployeeDirectory` maps `managerEmail` to `managerContact` the same way.

This small helper calculates VAT but it reads the rates from the environment and calls a remote service to validate tax numbers. How should it be layered?

```typescript
export async function invoiceTax(net: number, country: string, buyerVatId?: string) {
  const rates = JSON.parse(process.env.VAT_RATES ?? '{}');
  if (buyerVatId) {
    const r = await fetch(`https://vat-check.example/api/${buyerVatId}`);
    if ((await r.json()).valid && country !== 'DE') return { rate: 0, tax: 0, reverseCharge: true };
  }
  const rate = rates[country] ?? 0.19;
  return { rate, tax: Math.round(net * rate * 100) / 100, reverseCharge: false };
}
```

### Architectural Flaws
1. **The tax rule depends on configuration and HTTP:** reverse charge and rounding cannot be tested without `process.env` and a network call.
2. **Unvalidated inputs:** the rates JSON and the remote response are trusted as-is.

The rule itself is small, so a pure function plus two narrow interfaces is enough.

### Domain (`src/domain/vat.ts`)
```typescript
export interface VatLine {
  readonly rate: number;
  readonly tax: number;
  readonly reverseCharge: boolean;
}

export const SELLER_COUNTRY = 'DE';
export const DEFAULT_RATE = 0.19;

export function vatFor(net: number, rate: number, buyerCountry: string, buyerHasValidVatId: boolean): VatLine {
  if (buyerHasValidVatId && buyerCountry !== SELLER_COUNTRY) {
    return { rate: 0, tax: 0, reverseCharge: true };
  }
  return { rate, tax: Math.round(net * rate * 100) / 100, reverseCharge: false };
}
```

### Application (`src/application/CalculateInvoiceTax.ts`)
```typescript
import { DEFAULT_RATE, VatLine, vatFor } from '../domain/vat';

export interface VatRates { rateFor(country: string): number | undefined; }
export interface VatIdRegistry { isValid(vatId: string): Promise<boolean>; }

export class CalculateInvoiceTax {
  constructor(private readonly rates: VatRates, private readonly registry: VatIdRegistry) {}

  async execute(net: number, country: string, buyerVatId?: string): Promise<VatLine> {
    const valid = buyerVatId ? await this.registry.isValid(buyerVatId) : false;
    return vatFor(net, this.rates.rateFor(country) ?? DEFAULT_RATE, country, valid);
  }
}
```

### Infrastructure (`src/infrastructure/vat.ts`)
```typescript
export class EnvVatRates implements VatRates {
  private readonly rates: Record<string, number>;
  constructor(json: string | undefined) {
    this.rates = JSON.parse(json ?? '{}') as Record<string, number>;
  }
  rateFor(country: string): number | undefined { return this.rates[country]; }
}

export class HttpVatIdRegistry implements VatIdRegistry {
  async isValid(vatId: string): Promise<boolean> {
    const res = await fetch(`https://vat-check.example/api/${encodeURIComponent(vatId)}`);
    const body: unknown = await res.json();
    return typeof body === 'object' && body !== null && (body as { valid?: unknown }).valid === true;
  }
}
```
Wire it once: `new CalculateInvoiceTax(new EnvVatRates(process.env.VAT_RATES), new HttpVatIdRegistry())`. `vatFor(100, 0.19, 'FR', true)` now returns the reverse-charge line without any I/O.

Refactor the following typescript code to adhere strictly to Clean Architecture and Ports & Adapters:

```typescript
import { useState } from 'react';
import { supabase } from '../lib/supabase';

type Task = { id: string; title: string; status: 'todo' | 'doing' | 'done'; assignee: string | null };

export function TaskCard({ task, currentUser }: { task: Task; currentUser: string }) {
  const [error, setError] = useState('');

  async function advance() {
    const next = task.status === 'todo' ? 'doing' : task.status === 'doing' ? 'done' : null;
    if (!next) return setError('Task already done');
    if (next === 'doing' && task.assignee && task.assignee !== currentUser) {
      return setError('Only the assignee can start this task');
    }
    const { count } = await supabase.from('tasks').select('*', { count: 'exact', head: true })
      .eq('assignee', currentUser).eq('status', 'doing');
    if (next === 'doing' && (count ?? 0) >= 3) return setError('Finish a task before starting another');
    await supabase.from('tasks').update({ status: next, assignee: task.assignee ?? currentUser }).eq('id', task.id);
  }

  return (
    <div>
      <h3>{task.title}</h3>
      <button onClick={advance}>Advance</button>
      {error && <p role="alert">{error}</p>}
    </div>
  );
}

```

### Architectural Flaws in Original Code
1. **Workflow rules in a click handler:** status order, assignee ownership and the work-in-progress limit of 3 live in a React component.
2. **Database client in the UI:** Supabase queries run directly from the view.
3. **Inconsistent check order:** the WIP query runs even when the task is moving to `done`.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/task.ts`)
```typescript
import { Result } from '../shared/Result';

export type TaskStatus = 'todo' | 'doing' | 'done';

export interface Task {
  readonly id: string;
  readonly title: string;
  readonly status: TaskStatus;
  readonly assignee: string | null;
}

export type AdvanceError =
  | { kind: 'AlreadyDone' }
  | { kind: 'NotAssignee' }
  | { kind: 'WipLimitReached'; limit: number };

export const WIP_LIMIT = 3;

export function advance(task: Task, user: string, userTasksInProgress: number): Result<Task, AdvanceError> {
  if (task.status === 'done') return Result.fail({ kind: 'AlreadyDone' });
  if (task.status === 'todo') {
    if (task.assignee && task.assignee !== user) return Result.fail({ kind: 'NotAssignee' });
    if (userTasksInProgress >= WIP_LIMIT) return Result.fail({ kind: 'WipLimitReached', limit: WIP_LIMIT });
    return Result.ok({ ...task, status: 'doing', assignee: task.assignee ?? user });
  }
  return Result.ok({ ...task, status: 'done', assignee: task.assignee ?? user });
}
```

#### 2. Application Layer (`src/application/AdvanceTask.ts`)
```typescript
import { Result } from '../shared/Result';
import { AdvanceError, Task, advance } from '../domain/task';

export interface TaskStore {
  countInProgress(user: string): Promise<number>;
  update(task: Task): Promise<void>;
}

export class AdvanceTask {
  constructor(private readonly tasks: TaskStore) {}

  async execute(task: Task, user: string): Promise<Result<Task, AdvanceError>> {
    const inProgress = task.status === 'todo' ? await this.tasks.countInProgress(user) : 0;
    const next = advance(task, user, inProgress);
    if (!next.success) return next;
    await this.tasks.update(next.data);
    return next;
  }
}
