```typescript
import { Request, Response } from 'express';
import { getRepository } from 'typeorm';
import { Order } from '../entities/Order';
import { ReturnRequest } from '../entities/ReturnRequest';
import { shippo } from '../shippo';

export async function createReturn(req: Request, res: Response) {
  const order = await getRepository(Order).findOne(req.params.orderId, { relations: ['lines'] });
  if (!order || order.customerId !== req.user.id) return res.sendStatus(404);
  const line = order.lines.find((l) => l.id === req.body.lineId);
  if (!line) return res.status(400).json({ error: 'Unknown line' });
  const days = (Date.now() - order.deliveredAt.getTime()) / 86400000;
  const window = line.category === 'electronics' ? 15 : 30;
  if (days > window) return res.status(422).json({ error: `Return window of ${window} days has passed` });
  if (line.finalSale) return res.status(422).json({ error: 'Final sale items cannot be returned' });
  const label = await shippo.transaction.create({ rate: process.env.RETURN_RATE_ID, label_file_type: 'PDF' });
  const ret = await getRepository(ReturnRequest).save({
    orderId: order.id, lineId: line.id, labelUrl: label.label_url, refundCents: line.priceCents * line.qty,
  });
  res.status(201).json(ret);
}

```

### Architectural Flaws in Original Code
1. **Return policy in a controller:** the 15/30-day windows and the final-sale rule depend on Express and TypeORM.
2. **Global repository access:** `getRepository(...)` is a hidden dependency that cannot be swapped.
3. **Carrier SDK and environment in the flow:** the shipping label is created inline with `process.env`.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/returns.ts`)
```typescript
import { Result } from '../shared/Result';

export interface PurchasedLine {
  readonly id: string;
  readonly category: string;
  readonly finalSale: boolean;
  readonly priceCents: number;
  readonly qty: number;
}

export interface DeliveredOrder {
  readonly id: string;
  readonly customerId: string;
  readonly deliveredAt: Date;
  readonly lines: readonly PurchasedLine[];
}

export type ReturnError =
  | { kind: 'OrderNotFound' }
  | { kind: 'UnknownLine' }
  | { kind: 'WindowClosed'; windowDays: number }
  | { kind: 'FinalSale' };

export function returnWindowDays(line: PurchasedLine): number {
  return line.category === 'electronics' ? 15 : 30;
}

export function checkReturnable(order: DeliveredOrder, lineId: string, now: Date): Result<PurchasedLine, ReturnError> {
  const line = order.lines.find((l) => l.id === lineId);
  if (!line) return Result.fail({ kind: 'UnknownLine' });
  const days = (now.getTime() - order.deliveredAt.getTime()) / 86_400_000;
  const windowDays = returnWindowDays(line);
  if (days > windowDays) return Result.fail({ kind: 'WindowClosed', windowDays });
  if (line.finalSale) return Result.fail({ kind: 'FinalSale' });
  return Result.ok(line);
}
```

#### 2. Application Layer (`src/application/CreateReturn.ts`)
```typescript
import { Result } from '../shared/Result';
import { DeliveredOrder, ReturnError, checkReturnable } from '../domain/returns';

export interface ReturnRecord {
  readonly orderId: string;
  readonly lineId: string;
  readonly labelUrl: string;
  readonly refundCents: number;
}

export interface OrderReader { findWithLines(orderId: string): Promise<DeliveredOrder | null>; }
export interface ReturnLabels { create(): Promise<string>; }
export interface ReturnRepository { save(record: ReturnRecord): Promise<ReturnRecord>; }

export class CreateReturn {
  constructor(
    private readonly orders: OrderReader,
    private readonly labels: ReturnLabels,
    private readonly returns: ReturnRepository,
    private readonly now: () => Date,
  ) {}

  async execute(customerId: string, orderId: string, lineId: string): Promise<Result<ReturnRecord, ReturnError>> {
    const order = await this.orders.findWithLines(orderId);
    if (!order || order.customerId !== customerId) return Result.fail({ kind: 'OrderNotFound' });

    const line = checkReturnable(order, lineId, this.now());
    if (!line.success) return line;

    const labelUrl = await this.labels.create();
    const saved = await this.returns.save({
      orderId, lineId, labelUrl, refundCents: line.data.priceCents * line.data.qty,
    });
    return Result.ok(saved);
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/ShippoReturnLabels.ts`)
```typescript
