#### 4. Presentation Layer (`src/http/returnsController.ts`)
```typescript
import { Request, Response } from 'express';

function toHttp(error: ReturnError): [number, string | null] {
  switch (error.kind) {
    case 'OrderNotFound': return [404, null];
    case 'UnknownLine': return [400, 'Unknown line'];
    case 'WindowClosed': return [422, `Return window of ${error.windowDays} days has passed`];
    case 'FinalSale': return [422, 'Final sale items cannot be returned'];
  }
}

export const createReturnHandler = (createReturn: CreateReturn) => async (req: Request, res: Response) => {
  const result = await createReturn.execute(req.user.id, req.params.orderId, req.body.lineId);
  if (result.success) return res.status(201).json(result.data);
  const [status, message] = toHttp(result.error);
  return message ? res.status(status).json({ error: message }) : res.sendStatus(status);
};
