Refactor this Vue 3 composable for event RSVPs. Capacity and plus-one rules are mixed with Firestore calls:

```typescript
export function useRsvp(eventId: string) {
  const error = ref<string | null>(null);

  async function rsvp(userId: string, guests: number) {
    error.value = null;
    const eventRef = doc(db, 'events', eventId);
    await runTransaction(db, async (tx) => {
      const snap = await tx.get(eventRef);
      const ev = snap.data()!;
      if (ev.rsvpClosesAt.toDate() < new Date()) { error.value = 'RSVP closed'; return; }
      if (guests > ev.maxGuestsPerRsvp) { error.value = `Max ${ev.maxGuestsPerRsvp} guests`; return; }
      const seats = 1 + guests;
      if (ev.attending + seats > ev.capacity) {
        tx.set(doc(db, 'events', eventId, 'waitlist', userId), { guests, at: serverTimestamp() });
        error.value = 'Event full, you are on the waitlist';
        return;
      }
      tx.update(eventRef, { attending: ev.attending + seats });
      tx.set(doc(db, 'events', eventId, 'rsvps', userId), { guests });
    });
  }

  return { rsvp, error };
}
```

### Architectural Flaws in Original Code
1. **Event rules inside a UI composable:** closing time, guest limit and capacity are only testable with Vue and Firestore.
2. **Business outcome reported through a ref:** "waitlisted" is a valid outcome, but it is stored as an error string.
3. **Non-null assertion on the snapshot:** a deleted event crashes the transaction.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/rsvp.ts`)
```typescript
import { Result } from '../shared/Result';

export interface EventCapacity {
  readonly capacity: number;
  readonly attending: number;
  readonly maxGuestsPerRsvp: number;
  readonly rsvpClosesAt: Date;
}

export type RsvpOutcome = { kind: 'Confirmed'; seats: number } | { kind: 'Waitlisted' };
export type RsvpError = { kind: 'EventNotFound' } | { kind: 'Closed' } | { kind: 'TooManyGuests'; max: number };

export function decideRsvp(event: EventCapacity, guests: number, now: Date): Result<RsvpOutcome, RsvpError> {
  if (event.rsvpClosesAt < now) return Result.fail({ kind: 'Closed' });
  if (guests > event.maxGuestsPerRsvp) return Result.fail({ kind: 'TooManyGuests', max: event.maxGuestsPerRsvp });
  const seats = 1 + guests;
  if (event.attending + seats > event.capacity) return Result.ok({ kind: 'Waitlisted' });
  return Result.ok({ kind: 'Confirmed', seats });
}
```

#### 2. Application Layer (`src/application/Rsvp.ts`)
```typescript
import { Result } from '../shared/Result';
import { EventCapacity, RsvpError, RsvpOutcome, decideRsvp } from '../domain/rsvp';

export interface RsvpWrites {
  confirm(userId: string, guests: number, seats: number): void;
  waitlist(userId: string, guests: number): void;
}

export interface EventStore {
  /** Runs `work` atomically with the current event state (null if the event does not exist). */
  transact<T>(eventId: string, work: (event: EventCapacity | null, writes: RsvpWrites) => T): Promise<T>;
}

export class Rsvp {
  constructor(private readonly events: EventStore, private readonly now: () => Date) {}

  execute(eventId: string, userId: string, guests: number): Promise<Result<RsvpOutcome, RsvpError>> {
    return this.events.transact(eventId, (event, writes) => {
      if (!event) return Result.fail({ kind: 'EventNotFound' });
      const outcome = decideRsvp(event, guests, this.now());
      if (!outcome.success) return outcome;
      if (outcome.data.kind === 'Confirmed') writes.confirm(userId, guests, outcome.data.seats);
      else writes.waitlist(userId, guests);
      return outcome;
    });
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/FirestoreEventStore.ts`)
Firestore's `runTransaction`, `doc`, `serverTimestamp` and the `Timestamp.toDate()` conversion live only here: `transact` reads the event, builds a `RsvpWrites` that calls `tx.update(attending + seats)` and `tx.set` on the `rsvps` or `waitlist` sub-collection, then invokes `work`.

#### 4. Presentation Layer (`src/composables/useRsvp.ts`)
```typescript
function describe(error: RsvpError): string {
  switch (error.kind) {
    case 'EventNotFound': return 'Event not found';
    case 'Closed': return 'RSVP closed';
    case 'TooManyGuests': return `Max ${error.max} guests`;
  }
}

export function useRsvp(eventId: string, rsvpUseCase: Rsvp) {
  const error = ref<string | null>(null);
  const waitlisted = ref(false);

  async function rsvp(userId: string, guests: number) {
    error.value = null;
    const result = await rsvpUseCase.execute(eventId, userId, guests);
    if (!result.success) {
      error.value = describe(result.error);
      return;
    }
    waitlisted.value = result.data.kind === 'Waitlisted';
  }

  return { rsvp, error, waitlisted };
}
```
The view can now show the waitlist state on its own instead of reading it from an error message.

