```

### Architectural Flaws in Original Code
1. **Grading policy embedded in a data script:** the late penalty (10%), weighting and letter thresholds sit between Prisma and SendGrid calls.
2. **Deeply nested ORM include** shapes the whole algorithm around the database schema.
3. **Partial failure:** if a notification fails mid-loop, some grades are saved and others are not, with no record of which.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/grading.ts`)
```typescript
export interface Assignment {
  readonly id: string;
  readonly maxScore: number;
  readonly weight: number; // weights sum to 1
  readonly dueAt: Date;
}

export interface Submission {
  readonly assignmentId: string;
  readonly score: number;
  readonly submittedAt: Date;
}

export type Letter = 'A' | 'B' | 'C' | 'D' | 'F';

export interface FinalGrade { readonly percent: number; readonly letter: Letter; }

export const LATE_FACTOR = 0.9;

export function assignmentScore(a: Assignment, sub: Submission | undefined): number {
  if (!sub) return 0;
  const raw = sub.score / a.maxScore;
  return sub.submittedAt > a.dueAt ? raw * LATE_FACTOR : raw;
}

export function letterFor(percent: number): Letter {
  if (percent >= 90) return 'A';
  if (percent >= 80) return 'B';
  if (percent >= 70) return 'C';
  if (percent >= 60) return 'D';
  return 'F';
}

export function finalGrade(assignments: readonly Assignment[], submissions: readonly Submission[]): FinalGrade {
  const weighted = assignments.reduce(
    (sum, a) => sum + assignmentScore(a, submissions.find((s) => s.assignmentId === a.id)) * a.weight, 0);
  const percent = Math.round(weighted * 1000) / 10;
  return { percent, letter: letterFor(percent) };
}
```

#### 2. Application Layer (`src/application/PublishCourseGrades.ts`)
```typescript
import { Assignment, FinalGrade, Submission, finalGrade } from '../domain/grading';

export interface CourseRoster {
  readonly name: string;
  readonly assignments: readonly Assignment[];
  readonly students: readonly { enrollmentId: string; contact: string; submissions: readonly Submission[] }[];
}

export interface GradebookRepository {
  roster(courseId: string): Promise<CourseRoster | null>;
  saveFinalGrades(grades: ReadonlyMap<string, FinalGrade>): Promise<void>; // one transaction
}

export interface GradeNotifier {
  finalGrade(contact: string, courseName: string, grade: FinalGrade): Promise<void>;
}

export class PublishCourseGrades {
  constructor(private readonly gradebook: GradebookRepository, private readonly notifier: GradeNotifier) {}

  async execute(courseId: string): Promise<number | null> {
    const roster = await this.gradebook.roster(courseId);
    if (!roster) return null;
    const grades = new Map(roster.students.map((s) => [s.enrollmentId, finalGrade(roster.assignments, s.submissions)]));
    await this.gradebook.saveFinalGrades(grades);
    for (const s of roster.students) {
      const grade = grades.get(s.enrollmentId);
      if (grade) await this.notifier.finalGrade(s.contact, roster.name, grade);
    }
    return grades.size;
  }
}
```
All grades are persisted atomically before any notification is sent.

#### 3. Infrastructure Layer (`src/infrastructure/SendGridGradeNotifier.ts`)
