const AsyncStorage = require('@react-native-async-storage/async-storage').default;

async function logWorkout() {
  const today = new Date().toISOString().slice(0, 10);
  const state = JSON.parse((await AsyncStorage.getItem('streak')) || '{"count":0,"last":null,"freezes":1}');
  if (state.last === today) return state;
  const yesterday = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
  const twoDaysAgo = new Date(Date.now() - 2 * 86400000).toISOString().slice(0, 10);
  if (state.last === yesterday) state.count += 1;
  else if (state.last === twoDaysAgo && state.freezes > 0) { state.count += 1; state.freezes -= 1; }
  else state.count = 1;
  if (state.count % 7 === 0) state.freezes = Math.min(state.freezes + 1, 3);
  state.last = today;
  await AsyncStorage.setItem('streak', JSON.stringify(state));
  return state;
}

module.exports = { logWorkout };

```

### Architectural Flaws in Original Code
1. **Streak rules depend on device storage and the system clock:** the one-day gap, freeze consumption and the weekly freeze reward cannot be tested without React Native.
2. **Mutable untyped state** is parsed from a string and modified in place.

---

### Clean Architecture Refactoring (TypeScript)

#### 1. Domain Layer (`src/domain/streak.ts`)
Dates are plain `YYYY-MM-DD` strings so the rule is independent of time zones and clocks.
```typescript
export interface Streak {
  readonly count: number;
  readonly last: string | null;
  readonly freezes: number;
}

export const INITIAL_STREAK: Streak = { count: 0, last: null, freezes: 1 };
export const MAX_FREEZES = 3;

const shift = (day: string, deltaDays: number): string =>
  new Date(Date.parse(`${day}T00:00:00Z`) + deltaDays * 86_400_000).toISOString().slice(0, 10);

export function logWorkout(streak: Streak, today: string): Streak {
  if (streak.last === today) return streak;
  let { count, freezes } = streak;
  if (streak.last === shift(today, -1)) count += 1;
  else if (streak.last === shift(today, -2) && freezes > 0) { count += 1; freezes -= 1; }
  else count = 1;
  if (count % 7 === 0) freezes = Math.min(freezes + 1, MAX_FREEZES);
  return { count, freezes, last: today };
}
```

#### 2. Application Layer (`src/application/LogWorkout.ts`)
```typescript
import { INITIAL_STREAK, Streak, logWorkout } from '../domain/streak';

export interface StreakStore {
  load(): Promise<Streak | null>;
  save(streak: Streak): Promise<void>;
}

export class LogWorkout {
  constructor(private readonly store: StreakStore, private readonly today: () => string) {}

  async execute(): Promise<Streak> {
    const current = (await this.store.load()) ?? INITIAL_STREAK;
    const next = logWorkout(current, this.today());
    if (next !== current) await this.store.save(next);
    return next;
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/AsyncStorageStreakStore.ts`)
