  async load(): Promise<Streak | null> {
    const raw = await AsyncStorage.getItem('streak');
    return raw ? (JSON.parse(raw) as Streak) : null;
  }

  async save(streak: Streak): Promise<void> {
    await AsyncStorage.setItem('streak', JSON.stringify(streak));
