Refactor this concert ticketing route. Seat hold rules are implemented with raw Redis commands inside Express:

```typescript
app.post('/shows/:showId/holds', async (req, res) => {
  const { seats, sessionId } = req.body as { seats: string[]; sessionId: string };
  if (seats.length === 0 || seats.length > 8) return res.status(400).json({ error: 'Select 1 to 8 seats' });
  const existing = await redis.keys(`hold:${req.params.showId}:*:${sessionId}`);
  if (existing.length + seats.length > 8) return res.status(400).json({ error: 'Max 8 seats per session' });
  const sold = await redis.smembers(`sold:${req.params.showId}`);
  if (seats.some((s) => sold.includes(s))) return res.status(409).json({ error: 'Seat already sold' });
  const held: string[] = [];
  for (const seat of seats) {
    const ok = await redis.set(`hold:${req.params.showId}:${seat}:${sessionId}`, '1', 'EX', 600, 'NX');
    const other = await redis.keys(`hold:${req.params.showId}:${seat}:*`);
    if (!ok || other.length > 1) {
      for (const h of held) await redis.del(`hold:${req.params.showId}:${h}:${sessionId}`);
      return res.status(409).json({ error: `Seat ${seat} is held by someone else` });
    }
    held.push(seat);
  }
  res.status(201).json({ seats: held, expiresInSeconds: 600 });
});
```

### Architectural Flaws in Original Code
1. **Booking policy in Redis key patterns:** the 8-seat limit and 10-minute hold exist only as Express code around `KEYS` and `SET NX`.
2. **`KEYS` in a request path** scans the whole keyspace and is not safe in production.
3. **Race-prone holds:** a hold is set first and checked for conflicts afterwards.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/holds.ts`)
```typescript
import { Result } from '../shared/Result';

export const MAX_SEATS_PER_SESSION = 8;
export const HOLD_SECONDS = 600;

export type HoldError =
  | { kind: 'InvalidSelection' }
  | { kind: 'SessionLimit'; max: number }
  | { kind: 'SeatSold'; seat: string }
  | { kind: 'SeatHeld'; seat: string };

export function checkSelection(
  requested: readonly string[], alreadyHeld: number, sold: ReadonlySet<string>,
): Result<readonly string[], HoldError> {
  if (requested.length === 0 || requested.length > MAX_SEATS_PER_SESSION) return Result.fail({ kind: 'InvalidSelection' });
  if (alreadyHeld + requested.length > MAX_SEATS_PER_SESSION) {
    return Result.fail({ kind: 'SessionLimit', max: MAX_SEATS_PER_SESSION });
  }
  const soldSeat = requested.find((s) => sold.has(s));
  if (soldSeat) return Result.fail({ kind: 'SeatSold', seat: soldSeat });
  return Result.ok(requested);
}
```

#### 2. Application Layer (`src/application/HoldSeats.ts`)
```typescript
import { Result } from '../shared/Result';
import { HOLD_SECONDS, HoldError, checkSelection } from '../domain/holds';

export interface SeatInventory {
  soldSeats(showId: string): Promise<Set<string>>;
  heldBySession(showId: string, sessionId: string): Promise<number>;
  /** Holds all seats atomically, or none; returns the first seat that was already held. */
  holdAll(showId: string, sessionId: string, seats: readonly string[], ttlSeconds: number): Promise<string | null>;
}

export class HoldSeats {
  constructor(private readonly inventory: SeatInventory) {}

  async execute(showId: string, sessionId: string, seats: readonly string[]): Promise<Result<{ seats: readonly string[]; expiresInSeconds: number }, HoldError>> {
    const [held, sold] = await Promise.all([
      this.inventory.heldBySession(showId, sessionId),
      this.inventory.soldSeats(showId),
    ]);
    const selection = checkSelection(seats, held, sold);
    if (!selection.success) return selection;

    const conflict = await this.inventory.holdAll(showId, sessionId, selection.data, HOLD_SECONDS);
    if (conflict) return Result.fail({ kind: 'SeatHeld', seat: conflict });
    return Result.ok({ seats: selection.data, expiresInSeconds: HOLD_SECONDS });
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/RedisSeatInventory.ts`)
```typescript
import type { Redis } from 'ioredis';
import { SeatInventory } from '../application/HoldSeats';

// One key per seat (value = session) plus a per-session set; a Lua script makes the hold all-or-nothing.
const HOLD_ALL = `
for i, key in ipairs(KEYS) do
  local owner = redis.call('GET', key)
  if owner and owner ~= ARGV[1] then return ARGV[i + 2] end
end
for _, key in ipairs(KEYS) do redis.call('SET', key, ARGV[1], 'EX', ARGV[2]) end
return false`;

export class RedisSeatInventory implements SeatInventory {
  constructor(private readonly redis: Redis) {}

  async soldSeats(showId: string): Promise<Set<string>> {
    return new Set(await this.redis.smembers(`sold:${showId}`));
  }

  async heldBySession(showId: string, sessionId: string): Promise<number> {
    return this.redis.scard(`session-holds:${showId}:${sessionId}`);
  }

  async holdAll(showId: string, sessionId: string, seats: readonly string[], ttl: number): Promise<string | null> {
    const keys = seats.map((s) => `hold:${showId}:${s}`);
    const conflict = (await this.redis.eval(HOLD_ALL, keys.length, ...keys, sessionId, ttl, ...seats)) as string | null;
    if (!conflict) {
      await this.redis.multi().sadd(`session-holds:${showId}:${sessionId}`, ...seats)
        .expire(`session-holds:${showId}:${sessionId}`, ttl).exec();
    }
    return conflict;
  }
}
```

