```typescript
function toHttp(error: HoldError): [number, string] {
  switch (error.kind) {
    case 'InvalidSelection': return [400, 'Select 1 to 8 seats'];
    case 'SessionLimit': return [400, `Max ${error.max} seats per session`];
    case 'SeatSold': return [409, 'Seat already sold'];
    case 'SeatHeld': return [409, `Seat ${error.seat} is held by someone else`];
  }
}

app.post('/shows/:showId/holds', async (req, res) => {
