### Architectural Flaws in Original Code
1. **Delivery promise computed in a route:** the 12 km radius, kitchen load threshold and rush-hour buffers depend on hapi, Mongoose and Google Maps.
2. **Vendor response shape leaks:** `rows[0].elements[0]`, `duration_in_traffic` and status codes are read in the handler.
3. **Hidden clock and environment:** `new Date()` and `process.env.MAPS_KEY` are read per request.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/eta.ts`)
```typescript
import { Result } from '../shared/Result';

export interface Route { readonly meters: number; readonly seconds: number; }
export interface DeliveryWindow { readonly fromMinutes: number; readonly toMinutes: number; }
export type EtaError = { kind: 'StoreNotFound' } | { kind: 'Unreachable' } | { kind: 'OutsideArea' };

export const MAX_DELIVERY_METERS = 12_000;
export const WINDOW_WIDTH_MINUTES = 15;
const RUSH_HOURS: readonly [number, number][] = [[12, 14], [18, 21]];

export function prepMinutes(openOrders: number): number {
  return openOrders > 20 ? 25 : 15;
}

export function rushBuffer(localHour: number): number {
  return RUSH_HOURS.some(([from, to]) => localHour >= from && localHour < to) ? 10 : 0;
}

export function deliveryWindow(route: Route, openOrders: number, localHour: number): Result<DeliveryWindow, EtaError> {
  if (route.meters > MAX_DELIVERY_METERS) return Result.fail({ kind: 'OutsideArea' });
  const fromMinutes = Math.ceil(prepMinutes(openOrders) + route.seconds / 60 + rushBuffer(localHour));
  return Result.ok({ fromMinutes, toMinutes: fromMinutes + WINDOW_WIDTH_MINUTES });
}
```

#### 2. Application Layer (`src/application/EstimateDelivery.ts`)
```typescript
import { Result } from '../shared/Result';
import { DeliveryWindow, EtaError, Route, deliveryWindow } from '../domain/eta';

export interface Coordinates { readonly lat: number; readonly lng: number; }
export interface StoreInfo { readonly location: Coordinates; readonly openOrders: number; }

export interface StoreDirectory { find(storeId: string): Promise<StoreInfo | null>; }
export interface RoutePlanner { route(from: Coordinates, to: Coordinates): Promise<Route | null>; }

export class EstimateDelivery {
  constructor(
    private readonly stores: StoreDirectory,
    private readonly planner: RoutePlanner,
    private readonly localHour: () => number,
  ) {}

  async execute(storeId: string, destination: Coordinates): Promise<Result<DeliveryWindow, EtaError>> {
    const store = await this.stores.find(storeId);
    if (!store) return Result.fail({ kind: 'StoreNotFound' });
    const route = await this.planner.route(store.location, destination);
    if (!route) return Result.fail({ kind: 'Unreachable' });
    return deliveryWindow(route, store.openOrders, this.localHour());
  }
}
