#### 3. Infrastructure Layer (`src/infrastructure/GoogleRoutePlanner.ts`)
```typescript
import { Client } from '@googlemaps/google-maps-services-js';
import { Route } from '../domain/eta';
import { Coordinates, RoutePlanner } from '../application/EstimateDelivery';

export class GoogleRoutePlanner implements RoutePlanner {
  constructor(private readonly maps: Client, private readonly apiKey: string) {}

  async route(from: Coordinates, to: Coordinates): Promise<Route | null> {
    const matrix = await this.maps.distancematrix({ params: {
      origins: [`${from.lat},${from.lng}`], destinations: [`${to.lat},${to.lng}`], key: this.apiKey,
    } });
    const el = matrix.data.rows[0]?.elements[0];
    if (!el || el.status !== 'OK') return null;
    return { meters: el.distance.value, seconds: el.duration_in_traffic?.value ?? el.duration.value };
  }
}
